tap = []

screen = pygame.display.set_mode((WIDTH, HEIGHT), pygame.SCALED)
clock = pygame.time.Clock()
fullscreen = False

font = pygame.font.SysFont("comicsansms", 48)

pygame.mixer.music.load(resource_path("play-pretend.mp3"))

class Circles:
    def __init__(self, number):
        self.number = number
        self.colour = (240, 240, 240)

    def click(self):
        self.colour = (220, 220, 220)

    def unclick(self):
        self.colour = (240, 240, 240)

    def draw(self):
        pygame.draw.circle(screen, (0, 0, 0), (60 + self.number * 80, HEIGHT - 60), 32, width=0)
        pygame.draw.circle(screen, self.colour, (60 + self.number * 80, HEIGHT - 60), 30, width=0)

class Tap:
    def __init__(self, number, spawn_time):
        self.number = number
        self.spawn_time = abs(spawn_time) + 200
        self.y = 100

    def update_position(self, current_time, target_y, scroll_speed):
        time_difference = self.spawn_time - current_time
        self.y = target_y - (time_difference * scroll_speed)

    def draw(self):
        if -50 < self.y < HEIGHT + 50:
            pygame.draw.circle(screen, (0, 0, 0), (60 + self.number * 80, int(self.y)), 22, width=0)
            pygame.draw.circle(screen, (240, 240, 240), (60 + self.number * 80, int(self.y)), 20, width=0)

d = Circles(1)
f = Circles(2)
j = Circles(3)
k = Circles(4)

for t in chart:
    tap.append(Tap(t[0], t[1]))

keybinds = [pygame.K_d, pygame.K_f, pygame.K_j, pygame.K_k]
keys = [d, f, j, k]

circleY = HEIGHT - 60
bad = 100
margin = 40
good = 30
great = 20
perfect = 10

points = 0

SCROLL_SPEED = 0.5
start_ticks = pygame.mixer.music.get_pos()

pygame.mixer.music.play()

running = True
while running:
    screen.fill((240, 240, 240))
    
    current_time = pygame.time.get_ticks() - start_ticks

    for t in tap:
        t.update_position(current_time, circleY, SCROLL_SPEED)

    for t in reversed(tap):
        if t.y > circleY + bad:
            print("miss (passed bottom)")
            points -= 100
            tap.remove(t)

    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False

        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_F11:
                if fullscreen:
                    screen = pygame.display.set_mode((1280, 720), pygame.SCALED)
                    fullscreen = False
                else:
                    screen = pygame.display.set_mode((1280, 720), pygame.SCALED | pygame.FULLSCREEN)
                    fullscreen = True

            if event.key in keybinds:
                index = keybinds.index(event.key)
                keys[index].click()
                current_lane = index + 1

                for t in tap:
                    if t.number == current_lane:
                        pos = abs(t.y - circleY)
                        if pos <= bad:
                            tap.remove(t)
                            if pos < perfect:
                                print("perfect!")
                                points += 100
                            elif pos < great:
                                print("great!")
                                points += 80
                            elif pos < good:
                                print("good")
                                points += 50
                            elif pos < margin:
                                print("ok")
                                points += 20
                            else:
                                print("bad")
                                points -= 50
                            break

        if event.type == pygame.KEYUP:
            if event.key in keybinds:
                index = keybinds.index(event.key)
                keys[index].unclick()

    pointdisplay = font.render("pts: " + str(points), True, (0,0,0))
    screen.blit(pointdisplay,(400,100))

    d.draw()
    j.draw()
    k.draw()
    f.draw()

    for t in tap:
        t.draw()

    

    clock.tick(240)
    pygame.display.update()

pygame.quit()
